package com.example.starter;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

/**
 * 业务题目工程入口；提供生产批次隔离、放行、拆分血缘与召回追溯 Web 服务及数据库健康检查。
 */
@SpringBootApplication
public class StarterApplication {

    /**
     * 默认使用嵌入式 H2（MySQL 兼容模式）内存库启动，可通过 DB_URL/DB_USER 等环境变量覆盖。
     */
    public static void main(String[] args) {
        SpringApplication.run(StarterApplication.class, args);
    }
}

package com.example.starter.batch;

/**
 * 批次状态机。
 * QUARANTINED 初始隔离；全部必做检验项 PASS 后进入 PENDING_RELEASE；
 * 首个有效批准进入 RELEASE_REVIEW；第二个不同角色批准进入 RELEASED；
 * 任一 FAIL 立即进入 REJECTED（终态）；已放行批次召回后进入 RECALLED（终态）；
 * RELEASED 批次拆分后进入 SPLIT（终态，父批不再可用，可整体召回）。
 */
public enum BatchStatus {
    QUARANTINED,
    PENDING_RELEASE,
    RELEASE_REVIEW,
    RELEASED,
    REJECTED,
    RECALLED,
    SPLIT
}

package com.example.starter.batch;

/**
 * 幂等命令的已存储响应快照：HTTP 状态码 + 响应 JSON。
 */
public record StoredResponse(int status, String body) {
}

package com.example.starter.batch;

/**
 * 统一错误响应体：code 机器可区分，message 面向人。
 */
public record ErrorResponse(String code, String message) {
}

