public class LineageGuard {

    private final BatchRepository repo;

    public LineageGuard(BatchRepository repo) {
        this.repo = repo;
    }

    /**
     * 若任一级祖先已被召回则抛 422：后代批次禁止新增检验、批准、拆分与称量写入。
